WITH s(sku) AS (SELECT unnest(ARRAY['COPA10TWH','COPA9TWH','CRSFM110080BM','CRSFM110080WH','CRSFWL1HWN','CRSFWL2HWN','CRSFWR1CHWN','CRSFWR1CHWO','CRSFWR1LPWO','CRSFWR1THWO','CRSP60601BM','CRSP60603BM','CRSP60603WH','CRSP60605BM','CRSP60605WH','CRSP80303BM','CRSP80303CH','CRSP80303CO','CRSP80303SN','CRSP80303WH','CRSP80303YB','CRSP80304BM','CRSP80305BM','CRSP80305CH','CRSP80305CO','CRSP80305SN','CRSP80305WH','CRSP80305YB','IMACCW','IMACGR','IMACRG','IMACWW','IMACYE','IMYE','LHIFTE27BM','LHIFTE27CH','LHIFTE27YB','LHPLFTE14BM','LHPLFTE14WH','LHPLFTE27WH','LHPLHTE14BM','LHPLHTE14WH','LHPLPLE14BM','LHPLPLE14WH','LHPLPLE27BM','LHPLPLE27WH','LHPVC1E27WH','LHPVC2E27WH','LHPVGBWH','LHPVHRE27WH','LHPVSCE27WH','LHPVWBE27WB','LHSSB22GD','LHSWPBB22CH','LHSWPBB22GD','LHSWPBB22SN','LHTMCE27BM','LHTMPSE27BM','LHTT20E27YB','LHXBTF40E27BM','LHXBTF40E27WH','LHXBTH50E27BM','LHXBTH50E27WH','LHXCCE27BM','LHXCCE27RR','LHXCCE27WH','LHXDE27BM','LHXDE27WH','LHXIM30B22WH','LHXSHE27BM','LHXSHE27WH','LHXWPE27PPWH','LSACY195BG','LSAFT200BG','LSCY290DBI','LSCY290DBT','LSCY290DBU','LSCY290DCB','LSCY290DGD','LSCY290DGY','LSCY290DNB','LSCY290DOR','LSCY290DRE','LSCY290DWH','LSCY290DYE','LSF1HT400HE','LSFSDC1BM','LSFT220BW','LSFT255BD','LSFT255BI','LSFT255BT','LSFT255CB','LSFT255GR','LSFT255GY','LSFT255RE','LSFT255WH','LSGL10012AR','LSGL10014CL','LSGL15014CL','LSGL6016CL','LSGL606CL','LSGL7512CL','LSGL9015CL','LSGL9015GY','LSGL9015WH','LSGLBC160AR','LSGLBG130WH','LSGLBG145AR','LSGLBH150WS','LSGLBH300WS','LSGLBT200PU','LSGLCP120SY','LSGLDC160AS','LSGLFP245BL','LSGLFP245BR','LSGLFP245GR','LSGLFP245PU','LSGLLF170AR','LSGLSC115AR','LSGLTNAR','LSGLULCL','LSGLULSG','LSGLWB125TN','LSGLWM200YC','LSGLWS180YC','LSHM240BG','LSRD260AZ','LSRH260AZ','LSRT120AZ','LSSC310BI','LSSC310GR','LSSC310GY','LSSC310OR','LSSC310RE','PCRMFF','PHBAF1BMRBM','PHIFT1PBRBM','PHIFT1PBRYB','PHIFT1PCRCH','PHSH2BMTBM','PHSH2BMTYB','PHTC1PBRBM','PHTC1PCRCH','PHTC1PGRGD','PHXSH1PBRBM','PHXSH1PBRWH','PL4HBC','PL4HBM','PL4HRR','PLHNBC','PLH