SELECT json_agg(json_build_array(p.id,p.sku,p.created_at::date::text,
       left(COALESCE(NULLIF(p.eng_description,''),NULLIF(p.description,''),NULLIF(p.title,''),''),90),
       left(COALESCE(p.title,''),90), p.inventory_bool))::text AS j
FROM inventory.products p
WHERE EXISTS (SELECT 1 FROM s WHERE upper(p.sku)=upper(s.sku)
   OR p.sku ~ ('^'||s.sku||'[0-9A-Z]*PK$')
   OR (p.sku LIKE '%+%' AND ('+'||p.sku||'+') LIKE ('%+'||s.sku||'+%')));